const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1) Geometry & Dates
    const cityPoint = ee.Geometry.Point([-71.2488, -29.9045]);
    const roi = cityPoint.buffer(5000); // ~5 km buffer over La Serena
    const now = new Date();
    const currentYear = now.getFullYear();
    const targetYear = (now.getMonth() + 1 > 7 || (now.getMonth() + 1 === 7 && now.getDate() >= 7)) ? currentYear : currentYear - 1;
    const targetDateStr = `${targetYear}-07-07`;
    const startYTD = ee.Date.fromYMD(targetYear, 1, 1);
    const endYTD = ee.Date.fromYMD(targetYear, 7, 8); // exclusive end for inclusive Jul 7
    const climStartYear = 1990;
    const climEndYear = 2020;

    // 2) Dataset selectors
    const datasets = [
      {name: 'CHIRPS', id: 'UCSB-CHG/CHIRPS/DAILY', band: 'precipitation', factor: 1.0}, // mm/day
      {name: 'ERA5-Land', id: 'ECMWF/ERA5_LAND/DAILY_AGGR', band: 'total_precipitation_sum', factor: 1000.0} // m/day -> mm/day
    ];

    async function buildYtdSumImg(ds) {
      const col = ee.ImageCollection(ds.id).select(ds.band).filterDate(startYTD, endYTD);
      const size = await col.size().getInfo();
      return {col, size, img: col.sum().multiply(ds.factor).rename('precip')};
    }

    async function buildClimMeanImg(ds) {
      const years = ee.List.sequence(climStartYear, climEndYear);
      const ic = ee.ImageCollection(years.map(function(y) {
        y = ee.Number(y);
        const s = ee.Date.fromYMD(y, 1, 1);
        const e = ee.Date.fromYMD(y, 7, 8);
        return ee.ImageCollection(ds.id).select(ds.band).filterDate(s, e).sum().multiply(ds.factor).rename('precip')
                 .set('year', y);
      }));
      return {ic, img: ic.mean().rename('precip'), nYears: (climEndYear - climStartYear + 1)};
    }

    // 3) Try primary dataset, fallback if needed
    let chosen = null;
    let ytd = null;
    let clim = null;

    for (let i = 0; i < datasets.length; i++) {
      const ds = datasets[i];
      const y = await buildYtdSumImg(ds);
      if (y.size === 0) {
        if (i === datasets.length - 1) {
          console.log(`Target: ${targetDateStr}, Dataset tried: ${ds.name}`);
          console.log('No images found for YTD range.');
          console.log('C1');
          return;
        }
        continue;
      }
      const c = await buildClimMeanImg(ds);
      chosen = ds;
      ytd = y;
      clim = c;
      break;
    }

    // 4) Pixel counts and means
    const reducers = {
      mean: ee.Reducer.mean(),
      count: ee.Reducer.count()
    };

    const ytdCount = await ytd.img.reduceRegion({
      reducer: reducers.count,
      geometry: roi,
      scale: 5000,
      maxPixels: 1e9
    }).get('precip').getInfo();

    const climCount = await clim.img.reduceRegion({
      reducer: reducers.count,
      geometry: roi,
      scale: 5000,
      maxPixels: 1e9
    }).get('precip').getInfo();

    if (!ytdCount || !climCount || ytdCount === 0 || climCount === 0) {
      console.log(`Target: ${targetDateStr}, Dataset: ${chosen.name}`);
      console.log(`Pixels (YTD/Clim): ${ytdCount || 0} / ${climCount || 0}`);
      console.log('C2');
      return;
    }

    const ytdMean = await ytd.img.reduceRegion({
      reducer: reducers.mean,
      geometry: roi,
      scale: 5000,
      maxPixels: 1e9
    }).get('precip').getInfo();

    const climMean = await clim.img.reduceRegion({
      reducer: reducers.mean,
      geometry: roi,
      scale: 5000,
      maxPixels: 1e9
    }).get('precip').getInfo();

    // 5) Validation and deficit
    if (ytdMean === null || climMean === null || !isFinite(ytdMean) || !isFinite(climMean) || climMean <= 0) {
      console.log(`Target: ${targetDateStr}, Dataset: ${chosen.name}`);
      console.log(`Invalid stats. YTD: ${ytdMean}, Clim: ${climMean}`);
      console.log('C3');
      return;
    }

    const deficitPct = 100.0 * (climMean - ytdMean) / climMean;

    // 6) Prints (concise, <=20 lines)
    console.log(`Target: ${targetDateStr}, Dataset: ${chosen.name}`);
    console.log(`YTD images: ${ytd.size}, Clim years: ${clim.nYears}`);
    console.log(`Pixels (YTD/Clim): ${ytdCount} / ${climCount}`);
    console.log(`YTD total (mm): ${ytdMean.toFixed(1)}`);
    console.log(`Climatology mean 1990–2020 (mm): ${climMean.toFixed(1)}`);
    console.log(`Deficit (%): ${deficitPct.toFixed(1)}`);

    // 7) Final answer
    if (!isFinite(deficitPct)) {
      console.log('C3');
    } else if (deficitPct > 40.0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (e) {
    console.log(`Error: ${String(e).slice(0,180)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
